module nwz_mod
  use, intrinsic :: iso_c_binding
  implicit none

  private
    interface
      function get_nwz() bind(C, name="nwz_mod_nwz")
        import :: c_ptr, c_int
        type(c_ptr) :: get_nwz
      end function get_nwz
    end interface

  public :: nwz, nwz_mod_init, nwz_mod_finalize

  integer(c_int), pointer :: nwz => null()

contains
  subroutine nwz_mod_init()
    implicit none
    call c_f_pointer(get_nwz(), nwz)
  end subroutine nwz_mod_init

  subroutine nwz_mod_finalize()
    implicit none
    nwz => null()
  end subroutine nwz_mod_finalize
end module nwz_mod
